insert into smes (slug, registered_name, district, llg, primary_industry, secondary_industry, description, photo_ref, hero_photo_ref, featured, consent, approved, approved_at, is_sample) values ('abuta', 'Abuta Agro Services', 'Gazelle', 'Rakunai Village, Central Gazelle LLG', 'produce', null, 'A family-run cocoa nursery at Rakunai Village in Central Gazelle, raising healthy bagged cocoa seedlings for smallholder growers across the Gazelle Peninsula. Every seedling is grown under shade cloth and hardened off before sale, so it is ready to plant out the day it leaves the nursery. Bulk orders for new blocks and replanting are welcome.', 'GAZELLE_Abuta_business_01.jpg', 'GAZELLE_Abuta_frontpage_01.jpg', true, true, true, now(), true) on conflict (slug) do nothing;
insert into smes (slug, registered_name, district, llg, primary_industry, secondary_industry, description, photo_ref, hero_photo_ref, featured, consent, approved, approved_at, is_sample) values ('vunamami', 'Vunamami Growers Collective', 'Kokopo', null, 'produce', 'foodcrops', 'Smallholder growers from Vunamami village supplying fresh garden produce, vanilla and food crops across Kokopo District.', null, 'https://images.unsplash.com/photo-1533900298318-6b8da08a523e', true, true, true, now(), true) on conflict (slug) do nothing;
