with np as (insert into products (sme_id, name, category, price, unit, stock, description, perishable, status, badge, sort_key) select id, 'Cocoa Seedlings, Bagged & Ready to Plant', 'produce', 3, 'per seedling', 4800, 'Healthy cocoa seedlings raised in poly bags under shade cloth at Rakunai Village. Hardened off and ready to plant straight into the ground. Collect from the nursery in Central Gazelle, or order in bulk for delivery.', true, 'live', 'Local grower', 0 from smes where slug = 'abuta' returning id) insert into product_images (product_id, storage_path, photo_ref, sort_order) select id, 'GAZELLE_Abuta_seedlings_01.jpg', 'GAZELLE_Abuta_seedlings_01.jpg', 0 from np;
